TWICE = sorted([(t, int(c), int(p)) for (t, c, p), n in cites.items() if n >= 2])
def where(tr, c, p):
    ids = []
    for line in LED.split('\n'):
        if re.search(r'\b%s %d:%d\b' % (tr, c, p), line, re.I):   # the ledger's rows cite in capitals too (222:6 'BAVA METZIA 2:9') — the citing rows read case-blind
            g = re.match(r'- (Sifrei Devarim \d+:\d+|Onkelos Deut \d+:\d+)', line)
            ids.append(g.group(1).replace('Sifrei Devarim ', '') if g else (line[:40] + '…'))
    return ids
